// 시트 행 정리 (종목코드 빈 행은 건너뜀)
const now = DateTime.now().setZone('Asia/Seoul');
const parseDate = v => {
  let d = null;
  if (typeof v === 'number') {
    d = DateTime.fromObject({ year: 1899, month: 12, day: 30 }, { zone: 'Asia/Seoul' }).plus({ days: v });
  } else {
    const m = String(v ?? '').match(/(\d{4})\D+(\d{1,2})\D+(\d{1,2})/);
    if (m) d = DateTime.fromObject({ year: +m[1], month: +m[2], day: +m[3] }, { zone: 'Asia/Seoul' });
  }
  return d && d.isValid ? d : null;
};
return $input.all()
  .map((item, i) => ({ row: item.json, i }))
  .filter(({ row }) => String(row.ticker ?? '').trim() !== '')
  .map(({ row, i }) => {
    const d = parseDate(row.buy_date);
    const t = parseDate(row.track_from);
    // 고점 추적 시작일 = 매수일과 track_from(기준점 재설정일) 중 늦은 날
    const base = d && t ? (t > d ? t : d) : d;
    const code = String(row.ticker).trim().toUpperCase().replace(/\.(KS|KQ)$/, '');
    return {
      json: {
        ...row,
        code,
        code_ok: /^[0-9A-Z]{6}$/.test(code),
        buy_date_iso: d ? d.toISODate() : null,
        track_from_iso: t ? t.toISODate() : '',
        base_iso: base ? base.toISODate() : null,
        // 전일 대비 계산용으로 기준일 2주 전부터 조회
        date_from: base ? base.minus({ days: 14 }).toFormat('yyyyMMdd') : '',
        date_to: now.toFormat('yyyyMMdd'),
      },
      pairedItem: { item: i },
    };
  });

const cfg = $('Config').first().json;
const THRESHOLD = Number(cfg.threshold); // 예: -0.10
const row = $('Prepare').item.json;
const now = DateTime.now().setZone('Asia/Seoul');
const today = now.toISODate();

const num = x => { const n = Number(String(x ?? '').replace(/[,\s원]/g, '')); return x === '' || x == null || isNaN(n) ? null : n; };
const out = {
  row_number: row.row_number,
  account: String(row.account || '').trim() || '미지정',
  sub_account: String(row.sub_account || '').trim(),
  qty: num(row.qty),
  avg_price: num(row.avg_price),
  ticker: row.ticker,
  code: row.code,
  name: row.name || row.ticker,
  buy_date: row.buy_date_iso,
  track_from: row.track_from_iso,
  base_date: row.base_iso,
  checked_at: now.toFormat('yyyy-MM-dd HH:mm'),
  error: '',
  warn: '',
};
if (!row.code_ok) return { json: { ...out, error: 'ticker 형식 오류 (예: 005930)' } };
if (!row.buy_date_iso) return { json: { ...out, error: 'buy_date 형식 오류 (예: 2026-09-01)' } };
if ($json.rt_cd !== '0') return { json: { ...out, error: `KIS: ${$json.msg1 || $json.message || '응답 오류'} (${$json.msg_cd || ''})` } };

out.name = row.name || $json.output1?.hts_kor_isnm || row.ticker;
// output2: 최신순. 장 마감(15:30) 전 실행이면 오늘 행은 장중 가격이므로 제외 → 항상 확정 종가만 사용
const marketClosed = now.hour * 60 + now.minute >= 15 * 60 + 30;
const rows = ($json.output2 || []).filter(x => x.stck_bsop_date && x.stck_clpr);
const all = rows
  .map(x => ({ date: DateTime.fromFormat(x.stck_bsop_date, 'yyyyMMdd').toISODate(), close: Number(x.stck_clpr) }))
  .filter(b => marketClosed || b.date < today)
  .reverse(); // 오래된 → 최신
const bars = all.filter(b => b.date >= row.base_iso);
if (!bars.length) return { json: { ...out, error: '추적 시작일 이후 확정 종가 없음' } };

// API는 최대 100거래일. 추적 시작일이 그보다 오래되면 시트에 저장된 고점을 시작값으로 사용
const covered = rows.length < 100 || all[0].date <= row.base_iso;
let seed = null;
if (!covered) {
  const sp = num(row.peak_close), sd = String(row.peak_date || '');
  // 저장된 고점이 조회 구간보다 이전일 때만 시작값으로 사용 (구간 안이면 bars에 이미 포함)
  if (sp && sd >= row.base_iso) { if (sd < bars[0].date) seed = { date: sd, close: sp }; }
  else out.warn = '추적 시작일이 100거래일 이전 → 고점 부정확할 수 있음 (peak_close/peak_date 수동 입력)';
}

// 날짜별 누적 고점 → 현재 손절권 구간이 시작된 날 계산
let peak = seed || bars[0];
let breachSince = '';
for (const b of bars) {
  if (b.close > peak.close) peak = b;
  const inBreach = b.close / peak.close - 1 <= THRESHOLD;
  breachSince = inBreach ? (breachSince || b.date) : '';
}
const last = bars[bars.length - 1];
const prev = all[all.length - 2]; // 전 거래일 (매수일 이전 포함)
const dd = last.close / peak.close - 1;
const stop = Math.round(peak.close * (1 + THRESHOLD));

return {
  json: {
    ...out,
    peak_close: peak.close,
    peak_date: peak.date,
    last_close: last.close,
    last_date: last.date,
    day_change: prev ? +((last.close / prev.close - 1) * 100).toFixed(2) : null,
    drawdown: +(dd * 100).toFixed(2),
    stop_price: stop,
    stop_gap: +((stop / last.close - 1) * 100).toFixed(2), // 손절가까지 남은 % (음수=여유, 양수=이미 하회)
    breached: dd <= THRESHOLD,
    breach_since: breachSince,
    new_breach: !!breachSince && breachSince === last.date,
    // 손익 (수수료·세금 제외)
    ...(out.qty && out.avg_price ? (() => {
      const buy = out.qty * out.avg_price, ev = out.qty * last.close;
      return {
        buy_amount: Math.round(buy),
        eval_amount: Math.round(ev),
        pnl: Math.round(ev - buy),
        return_pct: +((ev / buy - 1) * 100).toFixed(2),
        day_pnl: prev ? Math.round(out.qty * (last.close - prev.close)) : 0,
      };
    })() : {}),
  },
};

// 전 종목 요약 메일 1통 (모바일 우선 단일 컬럼: 요약 → 손절 상태 → 시장 → 계좌 구성 → 종목 카드)
const cfg = $('Config').first().json;
const T = Number(cfg.threshold);
const now = DateTime.now().setZone('Asia/Seoul');
const today = now.toISODate();
const items = $input.all().map(i => i.json);

let manual = false;
try { manual = $('Manual Trigger').isExecuted; } catch (e) {}
try { manual = manual || $('수동 발송 (webhook)').isExecuted; } catch (e) {}
// 휴장일(오늘 종가 없음)에는 스케줄 실행 시 발송 안 함
if (!manual && !items.some(r => r.last_date === today)) return [];

const ok = items.filter(r => !r.error);
const bad = items.filter(r => r.error);
const breached = ok.filter(r => r.breached);
const fresh = breached.filter(r => r.new_breach);
const baseDate = ok.map(r => r.last_date).sort().pop() || today;

const fmt = n => (n == null ? '-' : Math.round(n).toLocaleString('ko-KR'));
const won = n => (n == null ? '-' : (n > 0 ? '+' : '') + Math.round(n).toLocaleString('ko-KR'));
const pct = n => (n == null ? '-' : (n > 0 ? '+' : '') + n.toFixed(2) + '%');
const md = s => (s || '').slice(5).replace('-', '/');
const idx = n => n.toLocaleString('ko-KR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const arrow = n => (n > 0 ? '▲' : n < 0 ? '▼' : '-');
const color = n => (n > 0 ? '#d60000' : n < 0 ? '#0051c7' : '#555');

const sum = rs => {
  const h = rs.filter(r => r.eval_amount != null);
  const buy = h.reduce((a, r) => a + r.buy_amount, 0), ev = h.reduce((a, r) => a + r.eval_amount, 0);
  const day = h.reduce((a, r) => a + (r.day_pnl || 0), 0);
  return { n: h.length, buy, ev, pnl: ev - buy, ret: buy ? (ev / buy - 1) * 100 : null, day, dayPct: ev - day ? (day / (ev - day)) * 100 : null };
};
const byOrder = order => (a, b) => (order.indexOf(a) + 1 || 99) - (order.indexOf(b) + 1 || 99);
const ORDER = ['일반', 'ISA', '연금'];
const ACC_COLOR = { 일반: '#2a78d6', ISA: '#eb6834', 연금: '#1baf7a' }; // 고정 순서, 계좌 구분용
const accounts = [...new Set(ok.map(r => r.account))].sort(byOrder(ORDER));
const total = sum(ok);
const SUB_ORDER = ['IRP', '퇴직연금', '연금저축'];
const subOf = r => r.sub_account || '미분류';

// 손절 여유: 고점→손절가 구간 중 남은 비율 (1=고점, 0=손절가)
const room = r => Math.max(0, Math.min(1, (r.last_close - r.stop_price) / (r.peak_close - r.stop_price)));
const state = r => r.breached ? { c: '#d03b3b', bg: '#fdecec', label: r.new_breach ? '🔴 손절권 신규' : `🔴 손절권 (${md(r.breach_since)}~)` }
  : room(r) < 0.3 ? { c: '#e09a00', bg: '#fff6e0', label: '⚠️ 주의' }
  : { c: '#0ca30c', bg: '', label: '' };

// 코스피 (KIS 업종 일봉: 최근 1개월). 실패해도 메일은 발송
let kospi = null;
try {
  const k = $('코스피 조회').first().json;
  if (k.rt_cd === '0') {
    const marketClosed = now.hour * 60 + now.minute >= 15 * 60 + 30;
    const bars = (k.output2 || [])
      .filter(x => x.stck_bsop_date && x.bstp_nmix_prpr)
      .map(x => ({ date: DateTime.fromFormat(x.stck_bsop_date, 'yyyyMMdd').toISODate(), close: Number(x.bstp_nmix_prpr) }))
      .filter(b => marketClosed || b.date < today) // 장중 값 제외 (종목 계산과 동일 기준)
      .reverse();
    const from = now.minus({ months: 1 }).toISODate();
    const series = bars.filter(b => b.date >= from);
    const base = [...bars].reverse().find(b => b.date < from) || series[0];
    const last = bars[bars.length - 1], prev = bars[bars.length - 2];
    if (last && prev && series.length > 1) kospi = {
      last, series,
      chg: last.close - prev.close,
      chgPct: (last.close / prev.close - 1) * 100,
      monthPct: (last.close / base.close - 1) * 100,
    };
  }
} catch (e) {}

// 제목
const parts = [];
if (total.n) parts.push(`오늘 ${won(total.day)} (${pct(total.dayPct)})`);
parts.push(breached.length ? `🔴 손절권 ${breached.length}` + (fresh.length ? ` (신규 ${fresh.length})` : '') : '✅ 손절권 없음');
if (bad.length) parts.push(`⚠️ 조회 실패 ${bad.length}`);
const subject = `[손절알리미] ${DateTime.fromISO(baseDate).toFormat('MM/dd')} ${parts.join(' · ')}`;

// 공통 스타일
const FONT = "-apple-system,'Apple SD Gothic Neo','Malgun Gothic',sans-serif";
const card = 'width:100%;table-layout:fixed;border-collapse:collapse;background:#fff;border:1px solid #e6e6e3;border-radius:10px;margin:0 0 12px;';
const h2 = 'margin:22px 0 8px;font-size:13px;font-weight:bold;color:#52514e;';
const muted = 'color:#888;font-size:12px;';
const dot = c => `<span style="display:inline-block;width:8px;height:8px;border-radius:4px;background:${c};margin-right:6px;"></span>`;

// 요약 카드 공통 (종합 / 계좌별): 합계 → 오늘·누적 → 도넛 → 표
const CAT = ['#2a78d6', '#eb6834', '#1baf7a', '#eda100', '#e87ba4', '#008300', '#6250d6', '#e34948']; // 검증된 범주색, 고정 순서
const accSums = accounts.map(a => [a, sum(ok.filter(r => r.account === a))]).filter(([, s]) => s.n);
const man = n => n >= 1e8 ? (n / 1e8).toFixed(2).replace(/\.?0+$/, '') + '억' : Math.round(n / 1e4).toLocaleString('ko-KR') + '만';
const shareOf = (v, tot) => (w => w.toFixed(w < 1 ? 1 : 0) + '%')(tot ? (v / tot) * 100 : 0);
const short = s => (s.length > 7 ? s.slice(0, 6) + '…' : s);

// 도넛: 조각마다 이름+평가금액, 8% 미만 조각은 바깥에 표시, 가운데 합계
const donutImg = (slices, centerLabel, tot) => {
  if (slices.length < 2) return '';
  const small = slices.map(x => x.value / tot < 0.08);
  const lbl = slices.map(x => [short(x.label), man(x.value)]);
  // 함수 포함 설정이라 JSON이 아닌 JS 문자열로 전달 (QuickChart 지원)
  const cfgJs = `{type:'doughnut',
data:{labels:${JSON.stringify(slices.map(x => x.label))},datasets:[{data:${JSON.stringify(slices.map(x => x.value))},
  backgroundColor:${JSON.stringify(slices.map(x => x.color))},borderColor:'#fff',borderWidth:2}]},
options:{cutoutPercentage:40,legend:{display:false},layout:{padding:34},
  plugins:{doughnutlabel:{labels:[{text:${JSON.stringify(centerLabel)},font:{size:11},color:'#888'},{text:${JSON.stringify(man(tot))},font:{size:15,weight:'bold'},color:'#1a1a1a'}]},
  datalabels:{
    formatter:(v,c)=>${JSON.stringify(lbl)}[c.dataIndex],
    anchor:c=>${JSON.stringify(small)}[c.dataIndex]?'end':'center',
    align:c=>${JSON.stringify(small)}[c.dataIndex]?'end':'center',
    offset:4,textAlign:'center',
    color:c=>${JSON.stringify(small)}[c.dataIndex]?'#333':'#fff',
    font:{size:12,weight:'bold',lineHeight:1.25}}}}}`;
  const src = 'https://quickchart.io/chart?w=270&h=270&devicePixelRatio=2&bkg=white&c=' + encodeURIComponent(cfgJs);
  return `<div style="text-align:center;">
  <img src="${src}" width="270" height="270" alt="${centerLabel} 평가금액 비중: ${slices.map(x => `${x.label} ${fmt(x.value)}원 ${shareOf(x.value, tot)}`).join(', ')}" style="display:inline-block;width:270px;max-width:100%;height:auto;">
</div>`;
};

// 카드 머리: 제목, 평가금액, 오늘 / 누적
const cardHead = (title, s, big, extraToday = '') => `
  <div style="${muted}">${title}</div>
  <div style="font-size:${big ? 28 : 22}px;font-weight:bold;letter-spacing:-0.5px;margin:2px 0 4px;">${fmt(s.ev)}<span style="font-size:${big ? 16 : 14}px;font-weight:normal;">원</span></div>
  <table role="presentation" style="width:100%;border-collapse:collapse;margin-top:8px;"><tr>
    <td style="width:50%;vertical-align:top;padding-right:8px;">
      <div style="${muted}">오늘</div>
      <div style="font-size:${big ? 17 : 15}px;font-weight:bold;color:${color(s.day)};">${won(s.day)}</div>
      <div style="font-size:12px;color:${color(s.day)};">${pct(s.dayPct)}${extraToday}</div>
    </td>
    <td style="width:50%;vertical-align:top;border-left:1px solid #eee;padding-left:14px;">
      <div style="${muted}">누적 평가손익</div>
      <div style="font-size:${big ? 17 : 15}px;font-weight:bold;color:${color(s.pnl)};">${won(s.pnl)}</div>
      <div style="font-size:12px;color:${color(s.pnl)};">${pct(s.ret)}<span style="color:#888;"> · 매입 ${fmt(s.buy)}</span></div>
    </td>
  </tr></table>
  <div style="border-top:1px solid #eee;margin-top:14px;"></div>`;

const numCell = (v, subTxt, c, extra = '') => `<td style="padding:8px 0 8px 8px;text-align:right;white-space:nowrap;vertical-align:top;${c ? 'color:' + c + ';' : ''}${extra}">${v}<div style="font-size:11px;${c ? '' : 'color:#888;'}">${subTxt}</div></td>`;

// 종합 카드 표 (일반 / ISA / 연금 / 전체)
const accRow = (label, s, c, strong) => `<tr>
  <td style="padding:9px 0;border-top:1px solid #eee;white-space:nowrap;${strong ? 'font-weight:bold;' : ''}">${c ? dot(c) : ''}${label}${!strong ? `<span style="${muted}margin-left:4px;">${shareOf(s.ev, total.ev)}</span>` : ''}</td>
  ${numCell(fmt(s.ev), '매입 ' + fmt(s.buy), null, 'border-top:1px solid #eee;' + (strong ? 'font-weight:bold;' : ''))}
  ${numCell(won(s.pnl), pct(s.ret), color(s.pnl), 'border-top:1px solid #eee;')}
  ${numCell(won(s.day), pct(s.dayPct), color(s.day), 'border-top:1px solid #eee;')}
</tr>`;
const accTable = `<table role="presentation" style="width:100%;border-collapse:collapse;font-size:14px;">
  <tr><td style="${muted}padding-bottom:4px;">계좌</td><td style="${muted}text-align:right;">평가금액</td><td style="${muted}text-align:right;">평가손익</td><td style="${muted}text-align:right;">오늘</td></tr>
  ${accSums.map(([a, s]) => accRow(a, s, ACC_COLOR[a])).join('')}
  ${accSums.length > 1 ? accRow('전체', total, null, true) : ''}
</table>`;

const vsKospi = kospi && total.dayPct != null && kospi.last.date === baseDate ? total.dayPct - kospi.chgPct : null;
const heroHtml = total.n ? `<table role="presentation" style="${card}"><tr><td style="padding:18px 18px 16px;">
  ${cardHead('총 평가금액', total, true, vsKospi != null ? `<span style="color:#888;"> · 코스피 대비 ${vsKospi > 0 ? '+' : ''}${vsKospi.toFixed(2)}%p</span>` : '')}
  ${donutImg(accSums.map(([a, s]) => ({ label: a, value: s.ev, color: ACC_COLOR[a] || '#999' })), '총 평가', total.ev)}
  ${accTable}
</td></tr></table>` : '';

// 2) 손절 상태 배너
const nearest = ok.filter(r => !r.breached && r.stop_price).sort((a, b) => room(a) - room(b))[0];
const statusHtml = breached.length
  ? `<table role="presentation" style="${card}border-color:#f3c2c2;background:#fdecec;"><tr><td style="padding:14px 16px;">
  <div style="font-size:15px;font-weight:bold;color:#b42323;">🔴 손절권 ${breached.length}종목${fresh.length ? ` (오늘 신규 ${fresh.length})` : ''}</div>
  ${breached.map(r => `<div style="margin-top:6px;font-size:13px;"><b>${r.name}</b> <span style="color:#666;">${r.account}${r.account === '연금' ? '·' + subOf(r) : ''}</span> · 고점대비 <b style="color:${color(r.drawdown)};">${pct(r.drawdown)}</b> · 손절가 ${fmt(r.stop_price)}${r.new_breach ? ' · <b>신규</b>' : ` · ${md(r.breach_since)}부터`}</div>`).join('')}
  <div style="margin-top:10px;font-size:12px;color:#7a2a2a;">시간외 종가(15:40~16:00) 또는 시간외 단일가(~18:00)로 당일 매도 가능 · 매도 후 시트 status를 <b>closed</b>로</div>
</td></tr></table>`
  : `<table role="presentation" style="${card}border-color:#cfe9cf;background:#f1faf1;"><tr><td style="padding:12px 16px;">
  <span style="font-size:14px;font-weight:bold;color:#0a7a0a;">✅ 손절권 종목 없음</span>
  ${nearest ? `<div style="font-size:12px;color:#52514e;margin-top:3px;">손절가에 가장 가까운 종목: <b>${nearest.name}</b> (손절가까지 ${(-nearest.stop_gap).toFixed(1)}% 남음)</div>` : ''}
</td></tr></table>`;

// 3) 시장 (코스피)
let kospiHtml = '';
if (kospi) {
  const chart = {
    type: 'line',
    data: {
      labels: kospi.series.map(b => DateTime.fromISO(b.date).toFormat('M/d')),
      datasets: [{ data: kospi.series.map(b => b.close), borderColor: '#2a78d6', backgroundColor: 'rgba(42,120,214,0.08)', borderWidth: 2, pointRadius: 0, lineTension: 0, fill: 'start' }],
    },
    options: {
      legend: { display: false },
      layout: { padding: { right: 8 } },
      scales: {
        xAxes: [{ gridLines: { display: false }, ticks: { maxTicksLimit: 5, maxRotation: 0, fontSize: 11, fontColor: '#999' } }],
        yAxes: [{ position: 'right', gridLines: { color: '#f0f0ee', drawBorder: false }, ticks: { maxTicksLimit: 4, fontSize: 11, fontColor: '#999' } }],
      },
    },
  };
  const src = 'https://quickchart.io/chart?w=560&h=140&devicePixelRatio=2&bkg=white&c=' + encodeURIComponent(JSON.stringify(chart));
  kospiHtml = `<div style="${h2}">시장</div>
<table role="presentation" style="${card}"><tr><td style="padding:14px 16px 4px;">
  <span style="font-size:13px;color:#52514e;">코스피</span>
  <span style="font-size:18px;font-weight:bold;margin-left:6px;">${idx(kospi.last.close)}</span>
  <span style="font-size:13px;font-weight:bold;color:${color(kospi.chg)};margin-left:4px;">${arrow(kospi.chg)}${idx(Math.abs(kospi.chg))} (${pct(kospi.chgPct)})</span>
  <div style="${muted}margin-top:2px;">최근 1개월 <span style="color:${color(kospi.monthPct)};">${pct(kospi.monthPct)}</span></div>
</td></tr><tr><td style="padding:0 6px 8px;">
  <img src="${src}" width="560" height="140" alt="코스피 최근 1개월 종가 추이" style="display:block;width:100%;max-width:560px;height:auto;">
</td></tr></table>`;
}

// 5) 계좌별 카드 (종합 카드와 같은 형식 + 고점대비 열). 종목은 손절가에 가까운 순
//    종목 이름은 한 줄 전체, 숫자 4열은 그 아래 줄 (모바일 폭 대응)
const sortRisk = rs => [...rs].sort((a, b) => room(a) - room(b));
const holdingRows = (r, c) => {
  const st = state(r);
  const bg = st.bg ? `background:${st.bg};` : '';
  return `<tr><td colspan="4" style="padding:10px 0 0;border-top:1px solid #eee;${bg}">
    <span style="font-size:14px;font-weight:bold;padding-left:${bg ? 6 : 0}px;">${c ? dot(c) : ''}${r.name}</span>
    <span style="${muted}margin-left:4px;">${fmt(r.qty)}주 · 평단 ${fmt(r.avg_price)} · 종가 ${fmt(r.last_close)}</span>
    ${r.warn ? `<span style="font-size:11px;color:#a60;margin-left:4px;">⚠️ 고점 확인 필요</span>` : ''}
  </td></tr>
  <tr style="${bg}font-size:13px;">
    ${numCell(fmt(r.eval_amount), '매입 ' + fmt(r.buy_amount), null)}
    ${numCell(won(r.pnl), pct(r.return_pct), color(r.pnl))}
    ${numCell(won(r.day_pnl), pct(r.day_change), color(r.day_pnl))}
    ${numCell(`${st.label ? (r.breached ? '🔴 ' : '⚠️ ') : ''}${pct(r.drawdown)}`, '고점 ' + fmt(r.peak_close), null, `padding-right:${bg ? 6 : 0}px;font-weight:${st.label ? 'bold' : 'normal'};color:${st.label ? st.c : color(r.drawdown)};`)}
  </tr>`;
};
const accountCard = ([acc, s]) => {
  const rs = ok.filter(r => r.account === acc && r.eval_amount != null);
  const pension = acc === '연금';
  const groups = pension
    ? [...new Set(rs.map(subOf))].sort(byOrder(SUB_ORDER)).map(g => [g, rs.filter(r => subOf(r) === g)])
    : [[null, rs]];
  const subColor = g => CAT[SUB_ORDER.indexOf(g)] || '#999';
  const holdColor = r => CAT[rs.indexOf(r)] || '#999'; // 시트 순서 고정 (정렬과 무관)
  const slices = pension
    ? groups.map(([g, grs]) => ({ label: g, value: sum(grs).ev, color: subColor(g) }))
    : rs.length <= CAT.length ? rs.map(r => ({ label: r.name, value: r.eval_amount, color: holdColor(r) })) : [];
  const body = groups.map(([g, grs]) => {
    const gs = sum(grs);
    const head = g === null ? '' : `<tr><td colspan="4" style="padding:8px 6px;border-top:1px solid #ddd;background:#f6f7f5;font-size:12px;">
  ${dot(subColor(g))}<b style="color:#333;">${g}</b><span style="color:#888;"> · ${fmt(gs.ev)}원 ${shareOf(gs.ev, s.ev)} · </span><span style="color:${color(gs.pnl)};">${won(gs.pnl)} (${pct(gs.ret)})</span></td></tr>`;
    return head + sortRisk(grs).map(r => holdingRows(r, pension ? null : holdColor(r))).join('');
  }).join('');
  return `<table role="presentation" style="${card}"><tr><td style="padding:16px 18px 12px;">
  ${cardHead(`${dot(ACC_COLOR[acc] || '#999')}<b style="color:#1a1a1a;font-size:14px;">${acc} 계좌</b>`, s, false)}
  ${donutImg(slices, acc, s.ev)}
  <table role="presentation" style="width:100%;table-layout:fixed;border-collapse:collapse;">
    <tr><td style="${muted}text-align:right;padding-bottom:4px;">평가금액</td><td style="${muted}text-align:right;">평가손익</td><td style="${muted}text-align:right;">오늘</td><td style="${muted}text-align:right;">고점대비</td></tr>
    ${body}
  </table>
</td></tr></table>`;
};
const holdingsHtml = `<div style="${h2}">계좌별 <span style="font-weight:normal;color:#999;">· 종목은 손절가에 가까운 순</span></div>${accSums.map(accountCard).join('')}`;

const badHtml = bad.length ? `<p style="color:#a60;font-size:13px;">⚠️ 조회 실패: ${bad.map(r => `${r.name} (${r.error})`).join(', ')}</p>` : '';
const noQty = ok.filter(r => r.eval_amount == null);
const noQtyHtml = noQty.length ? `<p style="color:#a60;font-size:12px;">수량/평균단가 미입력(손익 제외): ${noQty.map(r => r.name).join(', ')}</p>` : '';

const html = `<div style="background:#f4f4f2;padding:16px 12px;font-family:${FONT};color:#1a1a1a;">
<div style="max-width:600px;margin:0 auto;">
<div style="${muted}margin:0 4px 10px;">${DateTime.fromISO(baseDate).setLocale('ko').toFormat('M월 d일 (EEE)')} 종가 기준 · 고점 대비 ${(T * 100).toFixed(0)}% 이하 = 손절권</div>
${heroHtml}
${statusHtml}
${kospiHtml}
${holdingsHtml}
${noQtyHtml}${badHtml}
<p style="color:#999;font-size:11px;line-height:1.6;margin:14px 4px 0;">고점대비: ⚠️ 주의 = 손절가까지 여유 30% 미만 · 🔴 손절권 = 고점 대비 ${(T * 100).toFixed(0)}% 이하<br>평가손익은 수수료·세금 제외 · <a href="${cfg.sheet_url}" style="color:#2a78d6;">시트 열기</a></p>
</div></div>`;

const text = [
  `${baseDate} 종가 기준 (고점 대비 ${(T * 100).toFixed(0)}% 이하 = 손절권)`,
  total.n ? `총 평가 ${fmt(total.ev)} / 오늘 ${won(total.day)} (${pct(total.dayPct)}) / 누적 손익 ${won(total.pnl)} (${pct(total.ret)})` : '',
  breached.length ? `🔴 손절권: ${breached.map(r => `${r.name} ${pct(r.drawdown)}`).join(', ')}` : '✅ 손절권 없음',
  kospi ? `코스피 ${idx(kospi.last.close)} ${arrow(kospi.chg)} ${idx(Math.abs(kospi.chg))} (${pct(kospi.chgPct)}) · 1개월 ${pct(kospi.monthPct)}` : '',
  ...accounts.flatMap(a => {
    const rs = sortRisk(ok.filter(r => r.account === a)), s = sum(rs);
    return ['', `[${a} 계좌]` + (s.n ? ` 평가 ${fmt(s.ev)} / 손익 ${won(s.pnl)} (${pct(s.ret)})` : ''),
      ...rs.map(r => `${r.breached ? '🔴' : '  '} ${a === '연금' ? `[${subOf(r)}] ` : ''}${r.name}  종가 ${fmt(r.last_close)} (${pct(r.day_change)}) | 손익 ${won(r.pnl)} (${pct(r.return_pct)}) | 고점대비 ${pct(r.drawdown)} | 손절가 ${fmt(r.stop_price)} ${state(r).label}`)];
  }),
  ...(bad.length ? ['', '조회 실패: ' + bad.map(r => `${r.name} (${r.error})`).join(', ')] : []),
  '', cfg.sheet_url,
].join('\n');

return [{ json: { subject, html, text } }];
